SELECT 
FROM crm_merge_case
WHERE tenant_id = #{tenantId} AND id = #{id}

SELECT COUNT(*) FROM crm_merge_case
WHERE tenant_id = #{tenantId} AND primary_customer_id = #{primaryCustomerId}
  AND secondary_customer_id = #{secondaryCustomerId}

mapper.sql:
FROM crm_merge_case m
INNER JOIN crm_customer p ON p.tenant_id = m.tenant_id AND p.id = m.primary_customer_id
INNER JOIN crm_customer s ON s.tenant_id = m.tenant_id AND s.id = m.secondary_customer_id
WHERE m.tenant_id = #{tenantId}



    AND (p.owner_staff_id = #{selfId}

      OR p.team_id IN #{t}
    )
    AND (s.owner_staff_id = #{selfId}

      OR s.team_id IN #{t}
    )


    AND p.owner_staff_id = #{selfId} AND s.owner_staff_id = #{selfId}

  AND 1 = 0


  AND m.status = #{status}
